const CITYNAV_C_CURRENT_SHA := "a3e2c509e230b401c47bd1446af3676a74a9064a08b3781ae412edc2e47a9e88"
const CITYNAV_C_PARENT_SHA := "f1c8da74c69bf6660b2d9c9637b54e15d2679dfa7a2d75b1e0ed3f48a25374ab"
const CITYNAV_C_PROOF := "res://build/scene_cleanup_20261102c_system01/closure_READY01/C_cleanup_to_fixed_FINISH_C_inverse_READY.json"
const CITYNAV_C_PROOF_SHA := "7ee5ab34f9d74c7086372ff75669195d72025cc7e6e1a611071bc4a69b4b81de"
static func _citynav_c_fixed_parent_bytes() -> PackedByteArray:
	# Ordinary fixed predecessor only. Original older layers and author checks remain.
	if FileAccess.get_sha256(ORDINARY_C_PATH)!=CITYNAV_C_CURRENT_SHA or FileAccess.get_sha256(CITYNAV_C_PROOF)!=CITYNAV_C_PROOF_SHA: return PackedByteArray()
	var layer: Variant=JSON.parse_string(FileAccess.get_file_as_string(CITYNAV_C_PROOF))
	if not layer is Dictionary or layer.get("schema")!="CITYNAV_20261101D_FIXED_ORDINARY_WHOLEBYTE_LAYER_V1" or layer.get("path")!=ORDINARY_C_PATH or layer.get("current_sha256")!=CITYNAV_C_CURRENT_SHA or layer.get("parent_sha256")!=CITYNAV_C_PARENT_SHA or layer.get("whole_inverse_exact")!=true or not layer.get("hunks") is Array or layer.hunks.is_empty(): return PackedByteArray()
	var bytes: PackedByteArray=FileAccess.get_file_as_bytes(ORDINARY_C_PATH)
	if b().bytes_sha(bytes)!=CITYNAV_C_CURRENT_SHA: return PackedByteArray()
	for index: int in range(layer.hunks.size()-1,-1,-1):
		var row: Variant=layer.hunks[index]
		if not row is Dictionary or not row.get("new_offset") is float or not row.get("old") is String or not row.get("new") is String: return PackedByteArray()
		var start: int=int(row.new_offset)
		var native_new: PackedByteArray=String(row.new).to_utf8_buffer()
		if start<0 or start+native_new.size()>bytes.size() or bytes.slice(start,start+native_new.size())!=native_new: return PackedByteArray()
		bytes=bytes.slice(0,start)+String(row.old).to_utf8_buffer()+bytes.slice(start+native_new.size())
	return bytes if b().bytes_sha(bytes)==CITYNAV_C_PARENT_SHA else PackedByteArray()
